import{_ as t,c as o,o as i,ak as a}from"./chunks/framework.CjUXqSHI.js";const b=JSON.parse('{"title":"Queue internals & delivery tuning","description":"Dive into lifecycle configuration, leases, retries, and DLQ observability for PURISTA queues.","frontmatter":{"title":"Queue internals & delivery tuning","description":"Dive into lifecycle configuration, leases, retries, and DLQ observability for PURISTA queues.","order":299920},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/queues.md","filePath":"handbook/2_building_business-logic/advanced/queues.md","lastUpdated":1772037736000}'),d={name:"handbook/2_building_business-logic/advanced/queues.md"};function r(s,e,n,l,c,u){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="queue-internals-delivery-tuning" tabindex="-1">Queue internals &amp; delivery tuning <a class="header-anchor" href="#queue-internals-delivery-tuning" aria-label="Permalink to “Queue internals &amp; delivery tuning”">​</a></h1><p>The default queue builder hides most operational knobs, but production workloads often need precise control over leases, retries, and monitoring. This chapter explains how to tune those settings and what the runtime does under the hood.</p><h2 id="lifecycle-configuration" tabindex="-1">Lifecycle configuration <a class="header-anchor" href="#lifecycle-configuration" aria-label="Permalink to “Lifecycle configuration”">​</a></h2><p>Every queue definition can override the lifecycle defaults defined in <code>defaultQueueLifecycleConfig</code>:</p><table tabindex="0"><thead><tr><th>setting</th><th style="text-align:right;">default</th><th>impact</th></tr></thead><tbody><tr><td><code>visibilityTimeoutMs</code></td><td style="text-align:right;">15 minutes</td><td>How long a leased job stays invisible before it is re-queued. Increase for long-running jobs, decrease for quick bursts.</td></tr><tr><td><code>maxLeaseExtensions</code></td><td style="text-align:right;">3</td><td>Upper bound for <code>context.job.extendLease(ms)</code> before the runtime considers the job stuck.</td></tr><tr><td><code>heartbeatIntervalMs</code></td><td style="text-align:right;">5 minutes</td><td>How often the worker auto-extends leases when <code>autoHeartbeat</code> is true. Disable auto heartbeats for jobs that manage leases manually.</td></tr><tr><td><code>retryWindowMs</code></td><td style="text-align:right;">24 hours</td><td>Rolling time window for exponential backoff. After the window elapses, the retry strategy restarts with the initial delay.</td></tr><tr><td><code>maxAttempts</code></td><td style="text-align:right;">10</td><td>Number of <code>nack</code> retries before a job is moved to the DLQ. You can also override per enqueue call.</td></tr><tr><td><code>retryStrategy</code></td><td style="text-align:right;"><code>{ initialDelayMs: 1s, maxDelayMs: 120s, multiplier: 2, jitterFactor: 0.25 }</code></td><td>Controls the delay that <code>context.job.retry()</code> applies when you do not specify a custom <code>delayMs</code>.</td></tr></tbody></table><p>These values are applied when you call <code>.setLifecycleConfig(...)</code> on the queue builder. The CLI prompts for overrides so you can document changes as part of the scaffolded codebase.</p><h2 id="job-context-helpers" tabindex="-1">Job context helpers <a class="header-anchor" href="#job-context-helpers" aria-label="Permalink to “Job context helpers”">​</a></h2><p>Inside a worker handler (<code>setHandler(async function (context, message) { ... })</code>), the following helpers exist:</p><ul><li><code>context.job.complete(payload?)</code>: acknowledge the lease, optionally returning a payload that can be used by HTTP status endpoints.</li><li><code>context.job.retry({ delayMs?, reason? })</code>: negative acknowledge / requeue with optional delay. Retries count toward <code>maxAttempts</code>.</li><li><code>context.job.extendLease(ms)</code>: extend the visibility timeout proactively when a job is known to take longer.</li><li><code>context.job.moveToDeadLetter(reason?)</code>: skip retries entirely and send the job to the DLQ (useful for poison-pill scenarios).</li></ul><p>Each method emits OpenTelemetry spans/tags so you can observe queue health in tracing tools.</p><h2 id="dead-letter-queues-observability" tabindex="-1">Dead-letter queues &amp; observability <a class="header-anchor" href="#dead-letter-queues-observability" aria-label="Permalink to “Dead-letter queues &amp; observability”">​</a></h2><p>Queue bridges expose <code>metrics(queueName)</code> and, when supported, <code>deadLetterInspectable</code>:</p><ul><li><code>pending</code>, <code>inflight</code>, <code>deadLetter</code>, <code>retries</code>, <code>oldestAgeMs</code> help you decide when to scale workers or investigate stuck jobs.</li><li>When <code>deadLetterInspectable</code> is true (Default and Redis bridges support it), DLQ contents can be listed or re-processed via bridge-specific tooling.</li><li>Emit custom events or alerts in your worker when <code>context.job.retry()</code> hits <code>maxAttempts</code> so SREs see DLQ growth before SLAs are impacted.</li></ul><h2 id="delivery-semantics" tabindex="-1">Delivery semantics <a class="header-anchor" href="#delivery-semantics" aria-label="Permalink to “Delivery semantics”">​</a></h2><p>Queues are <strong>at-least-once by design</strong>: if a worker crashes before calling <code>complete</code>, the job is re-queued. Make handlers idempotent (use idempotency keys, versioned state, or side-effect guards) to avoid duplicated work when retries happen. Combine queue lifecycles with the event bridge semantics documented in <a href="./delivery-semantics-and-reliability.html">Delivery semantics and reliability</a> for a full end-to-end picture.</p>',15)])])}const p=t(d,[["render",r]]);export{b as __pageData,p as default};
